action.code:
if (open_list.empty()) return nullptr;

auto lowest_it = std::min_element(open_list.begin(), open_list.end(),
    [](RouteModel::Node* a, RouteModel::Node* b) {
        return (a->g_value + a->h_value) < (b->g_value + b->h_value);
    });

RouteModel::Node* lowest_node = *lowest_it;
open_list.erase(lowest_it);
return lowest_node;

